-- إصلاحُ الملخَّصات المبتورة.
-- وُلِّد آليًّا بـ scripts/repair-truncated-summaries.py: كلُّ حرفٍ مُضافٍ
-- منقولٌ بحرفه من حقل body الخاصِّ بالصفِّ نفسِه، لا من خارجه.
BEGIN;
UPDATE sharia_rulings SET summary = 'هذه المراتب الثلاث جاءت في حديث جبريل الشهير المتفق عليه وهو من أجمع الأحاديث: (1) الإسلام: هو الاستسلام الظاهر بالأركان الخمسة — الشهادتان، الصلاة، الزكاة، الصوم، الحج…'
  WHERE id = '64b3a4fb-b93a-4b17-9606-6c1e21699bf2';
UPDATE sharia_rulings SET summary = 'العمرة: زيارة البيت الحرام مع أداء مناسك خاصة. أركانها: (1) الإحرام من الميقات. (2) الطواف سبعة أشواط. (3) السعي بين الصفا والمروة. (4) الحلق أو التقصير. الفرق عن الحج: (أ) الحج فرض مرة في العمر لمن استطاع، والعمرة واجبة عند بعض أو سنة مؤكدة…'
  WHERE id = '64e02b14-ef8e-4581-918c-699d675dba39';
UPDATE sharia_rulings SET summary = 'حدّد القرآن الكريم مصارف الزكاة في ثمانية أصناف: (1) الفقراء: من لا يجد كفايته. (2) المساكين: من يجد بعض كفايته. (3) العاملون عليها: جُباتها والمشرفون عليها. (4) المؤلفة قلوبهم: من يُرجى إسلامهم أو كفّ شرهم…'
  WHERE id = '670cc8c6-f362-44db-80c1-4cac7a1e0136';
UPDATE sharia_rulings SET summary = 'الإجارة عقد معاوضة على منفعة بأجر محدد؛ المستأجر يدفع مبلغاً معلوماً مقابل منفعة معلومة، والعامل يضمن العمل ولا يتحمل الربح والخسارة. المضاربة: عقد شركة بين مالك رأس المال والعامل (المضارب)؛ الربح يُقسم بنسبة متفق عليها، والخسارة على المال لا على العامل إلا بتقصير…'
  WHERE id = '697c0f88-d098-4844-a2a1-e5b860a249de';
UPDATE sharia_rulings SET summary = 'الصيام في السفر جائز والإفطار جائز. المسألة الثانية: أيّهما أفضل؟ اختلف العلماء على ثلاثة أقوال: 1) الصيام أفضل إن لم يشق (الشافعية، بعض الحنابلة). 2) الإفطار أفضل مطلقاً عملاً بالرخصة (بعض الصحابة والتابعين)…'
  WHERE id = '6e2c22c9-8ea0-455c-a454-0fe4a4a75672';
UPDATE sharia_rulings SET summary = 'غزوة بدر كانت في ١٧ رمضان من السنة الثانية للهجرة. المسلمون: ٣١٣ رجلاً بقيادة النبي ﷺ. قريش: نحو ١٠٠٠ مقاتل بقيادة أبي جهل. نتيجتها: نصر مبين للمسلمين، قُتل من قريش ٧٠ وأُسر ٧٠…'
  WHERE id = '6f8ce962-216a-4ded-a062-6f5e76eaf2d9';
UPDATE sharia_rulings SET summary = 'شروط وجوب الحج: (1) الإسلام. (2) العقل. (3) البلوغ. (4) الحرية. (5) الاستطاعة المالية والبدنية وأمن الطريق. أما الفرق بين الحج والعمرة: الحج له وقت محدد (أشهر الحج)، وأركانه: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي…'
  WHERE id = '73740b71-d677-4fff-aeda-0e8262c9483a';
UPDATE sharia_rulings SET summary = 'اختلف المعاصرون في التصوير الفوتوغرافي والرقمي. فذهب كثيرون إلى أنه مباح لأنه مجرد تثبيت الضوء وهو لا يُعدّ خلقاً. وذهب آخرون إلى الكراهة أو التحريم إن كان لغير حاجة…'
  WHERE id = '73933d39-8553-427b-8712-3d1ad17103f1';
UPDATE sharia_rulings SET summary = 'غزوة أحد (٣ هـ) كانت اختباراً للصبر والانضباط. أبرز ما يُستفاد منها: (1) معصية الأمر سبب الهزيمة — تركُ الرماة مواقعهم طمعاً في الغنيمة أدّى إلى الانقلاب على المسلمين…'
  WHERE id = '73abf900-a288-4a19-8fc6-3fd0e751525d';
UPDATE sharia_rulings SET summary = 'قراءة القرآن من الهاتف الذكي جائزة وصحيحة، وثوابها كثواب القراءة من المصحف. وقد أفتى بذلك جمهور العلماء المعاصرين. وأما مسألة لمس الهاتف على غير طهارة: فالراجح أن اشتراط الطهارة كان لمصحف خاص به، والهاتف أداة متعددة الأغراض فلا يشترط لها الطهارة وإن كان الأفضل أن يكون المرء على طهارة تعظيماً لكلام الله.'
  WHERE id = '73fbbcde-f424-40c8-8cdb-9bc2ec44a88b';
UPDATE sharia_rulings SET summary = 'غزوة بدر (٢ هـ) أول معركة كبرى في الإسلام، وفيها دروس عظيمة: (1) التوكل مع الأخذ بالأسباب — خرج المسلمون بثلاثمائة وبضعة عشر رجلاً في مواجهة جيش قريش المدجَّج. (2) تحقيق وعد الله بنصر المؤمنين — قُتل صناديد قريش وأُسر كبارهم…'
  WHERE id = '7624737e-6b08-4693-b79a-8513f2f0462a';
UPDATE sharia_rulings SET summary = 'نعم، يشترط إذن الزوج لصيام التطوع عند وجوده في البيت؛ لحديث: «لا تصوم المرأة وبعلها شاهد إلا بإذنه» — رواه البخاري (5192) ومسلم (1026). أما صيام الفرض (رمضان والقضاء والنذر) فلا يحتاج إذناً…'
  WHERE id = '76b834b8-4a7c-4288-8b6e-ef67b6fa3e35';
UPDATE sharia_rulings SET summary = 'من أذكار الاستيقاظ: «الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور»، و«لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، سبحان الله والحمد لله ولا إله إلا الله والله أكبر ولا حول ولا قوة إلا بالله»…'
  WHERE id = '775d57ea-a85b-4286-b0d6-cc4a6abae365';
UPDATE sharia_rulings SET summary = 'موسى بن عمران عليه السلام من أولي العزم من الرسل. أبرز محطاته: (1) ولادته وإلقاؤه في اليم وإنقاذ فرعون له. (2) نشأته في قصر فرعون. (3) فراره إلى مدين بعد قتل الرجل…'
  WHERE id = '78e095e3-b0d1-4aa0-a33d-542066769400';
UPDATE sharia_rulings SET summary = 'اختُص النبي ﷺ بخصائص منها: (1) خاتم الأنبياء والمرسلين. (2) أُرسل للناس كافة ليس لقوم بعينهم. (3) رسالته باقية إلى يوم القيامة. (4) أُعطي جوامع الكلم. (5) أُحلّت له الغنائم ولم تُحَلّ لمن قبله…'
  WHERE id = '7c3f96d1-a714-43bd-a344-e7afe3e54d34';
UPDATE sharia_rulings SET summary = 'يجب الغسل على المرأة في الحالات التالية: (1) الإنزال (المني) يقظةً أو منامًا. (2) الجماع وإن لم ينزل. (3) انقطاع الحيض. (4) انقطاع النفاس (دم ما بعد الولادة). ويختص بها هذان الأخيران دون الرجل…'
  WHERE id = '7d25a42d-779c-40d9-bbb2-12935d503f21';
UPDATE sharia_rulings SET summary = 'الحديث المتواتر: ما رواه عدد كبير يستحيل تواطؤهم على الكذب، وهو يُفيد اليقين ويجب الاعتقاد به. والآحاد: ما لم يبلغ حد التواتر، وهو يُفيد الظن الغالب ويجب العمل به في الأحكام عند جمهور العلماء…'
  WHERE id = '7da27a48-179a-4507-ba20-87f9f1ab0e1f';
UPDATE sharia_rulings SET summary = 'قال ﷺ: ''لا يرد القضاء إلا الدعاء، ولا يزيد في العمر إلا البر'' (صحّحه الألباني). ومعناه: أن الدعاء سبب مقدَّر من الله كغيره من الأسباب. الله قدَّر السبب والنتيجة معاً: قدَّر أن هذا الشخص يدعو فيُرزق، وقدَّر أن ذاك يترك الدعاء فلا يُرزق…'
  WHERE id = '7e01e406-cb1a-4f57-b95f-fad6e4dc54a8';
UPDATE sharia_rulings SET summary = 'أبو ذر الغفاري (جُندب بن جنادة) رضي الله عنه من كبار الصحابة وأولهم إسلاماً. أسلم مبكراً قبل الهجرة وكان خامساً أو رابعاً في الإسلام. قال عنه النبي ﷺ: ''ما أظلّت الخضراء ولا أقلّت الغبراء من رجل أصدق لهجةً من أبي ذر''…'
  WHERE id = '7e43999f-eff9-4f20-87da-5fa57137795c';
UPDATE sharia_rulings SET summary = 'الديون المرجوة (التي يُتوقع استردادها) يرى جمهور العلماء أن عليها الزكاة عن كل سنة ماضية عند القبض. والأموال المودعة في البنك زكاتها واجبة عن كل سنة تبلغ فيها النصاب، لأنها في حكم النقد الحاضر…'
  WHERE id = '7e5239d3-6d8f-48cb-bb11-7f9cb12de3f3';
UPDATE sharia_rulings SET summary = 'القراءات القرآنية العشر المتواترة كلها قرآن ثابت صحيح المتن والسند، ولا يجوز القول بأن قراءة أحسن من أخرى. حكم الصلاة بها: تجوز الصلاة بأي قراءة من القراءات العشر المتواترة، وقد أجمع الفقهاء على ذلك…'
  WHERE id = '7e91c1b3-e548-410a-be44-40bc902e246d';
UPDATE sharia_rulings SET summary = 'الحديث القدسي هو ما رواه النبي صلى الله عليه وسلم عن ربه بلفظه الخاص، فمعناه من الله وصياغته من النبي. يختلف عن القرآن في أن القرآن متعبَّد بتلاوته، متحدى به، ومنقول بالتواتر، بينما الحديث القدسي يُنقل آحاداً ولا يُتعبَّد بتلاوته.'
  WHERE id = '7faeba51-354a-48a6-a54b-e0666b00e22e';
UPDATE sharia_rulings SET summary = 'الوقف حبس الأصل وتسبيل المنفعة في وجه من وجوه البر. حكمه: مستحب وله فضل عظيم — قال النبي ﷺ: «إذا مات ابن آدم انقطع عمله إلا من ثلاث... وصدقة جارية». شروطه: (1) الواقف: مسلم مكلف حر…'
  WHERE id = '80a0f48b-025b-44ca-bd44-7b5d0b98dc8f';
UPDATE sharia_rulings SET summary = 'أبرز محطات الهجرة النبوية: (1) الخروج من مكة سراً ليلاً ومبيته ﷺ مع أبي بكر في غار ثور ثلاثة أيام. (2) سلوكهما طريقاً غير مألوفة على الساحل هرباً من المشركين. (3) المرور بـ«أم معبد» وشرب لبن شاتها المبارك…'
  WHERE id = '81359544-82e8-4f61-a758-ab5ceaa91b7d';
UPDATE sharia_rulings SET summary = 'مسألة خلافية: ذهب الإمام أحمد وإسحاق إلى وجوب الوضوء من لحم الإبل، وهو مذهب الحنابلة، للحديث الصريح: سُئل النبي ﷺ عن الوضوء من لحوم الإبل فقال: «نعم فتوضأ منها» (مسلم — 360)…'
  WHERE id = '816f564c-2a8c-4fe4-8968-96acb2509c96';
UPDATE sharia_rulings SET summary = 'مرّ جمع القرآن بمرحلتين: (1) عهد أبي بكر — بعد موقعة اليمامة (١٢ هـ) استُشهد سبعون قارئاً، فأشار عمر بجمعه، فأمر أبو بكر زيد بن ثابت بجمعه في مصحف واحد من الصدور والقراطيس…'
  WHERE id = '825f47a6-68e8-47a2-a813-18db8426eb08';
UPDATE sharia_rulings SET summary = 'اختلف الفقهاء في أخذ الأجرة على تعليم القرآن: (1) المذهب الحنفي القديم: يكره أو يحرم لأن التعليم من فروض الكفاية. (2) الجمهور (مالكية وشافعية وحنابلة): يجوز أخذ الأجرة على تعليم القرآن والعلم الشرعي للحاجة، واحتجوا بقصة الصحابي الذي أخذ غنماً على الرقية بالفاتحة…'
  WHERE id = '8284960f-0320-41e0-90ca-dd8b3721718f';
UPDATE sharia_rulings SET summary = 'اشترط الجمهور (المالكية والشافعية والحنابلة) لصحة المسح على الخفين والجوارب: أن تكون ساترة لمحل الفرض (القدم مع الكعب) وأن تثبت بنفسها وأن تكون طاهرة. فالجوارب الشفافة الرقيقة التي تظهر منها البشرة لا يصح المسح عليها عند الجمهور لعدم الستر…'
  WHERE id = '82fa8a8f-6905-4ad6-9dae-d3afc18844ad';
UPDATE sharia_rulings SET summary = 'السنن الرواتب هي النوافل المؤكدة المرتبطة بالصلوات المكتوبة قبلها أو بعدها. وأصحّ ما ورد في عددها: اثنتا عشرة ركعة — ركعتان قبل الفجر، وأربع قبل الظهر وركعتان بعدها، وركعتان بعد المغرب، وركعتان بعد العشاء…'
  WHERE id = '8452d902-5542-4b26-b03b-c556b0df4d17';
UPDATE sharia_rulings SET summary = 'المكي: ما نزل قبل الهجرة النبوية ولو في غير مكة. المدني: ما نزل بعد الهجرة ولو في غير المدينة. فائدة معرفة ذلك: (1) معرفة مراحل التشريع الإسلامي — المكي يُركّز على العقيدة والأخلاق، والمدني يُفصّل الأحكام والتشريعات…'
  WHERE id = '85233bda-5282-4ab6-8969-17287da8c0f6';
COMMIT;
